# Example 1: Basic Thompson Sampling
import numpy as np

class SimpleThompsonBandit:
    def __init__(self, n_arms=3):
        self.alpha = np.ones(n_arms)  # Successes + 1
        self.beta = np.ones(n_arms)   # Failures + 1

    def select_arm(self):
        # Sample from Beta distribution for each arm
        samples = np.random.beta(self.alpha, self.beta)
        return np.argmax(samples)

    def update(self, arm, reward):
        if reward > 0.5:
            self.alpha[arm] += 1
        else:
            self.beta[arm] += 1

    def get_stats(self):
        # Expected reward = alpha / (alpha + beta)
        return self.alpha / (self.alpha + self.beta)

# Simulate
bandit = SimpleThompsonBandit(n_arms=3)
true_rewards = [0.3, 0.7, 0.5]  # Tool 1 is best

for _ in range(100):
    arm = bandit.select_arm()
    reward = 1.0 if np.random.random() < true_rewards[arm] else 0.0
    bandit.update(arm, reward)

print("Learned rewards:", bandit.get_stats())
print("True rewards:", true_rewards)
# Learned rewards should converge to true!

